/* VVS reuses the owner case; the outer frame stays compact on small screens. */
.vvs-demo:has(.followup-demo){padding:14px}.vvs-demo>.fu-top{margin-bottom:8px}.vvs-demo .followup-demo{padding:10px 0 0}.vvs-demo>.fu-actions{margin-bottom:4px}
.vvs-demo .followup-demo>.fu-top button{display:none}.demo-tabs{flex-wrap:wrap}.demo-tabs>button{min-width:0}
@media(max-width:600px){.demo-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.demo-tabs>button{width:100%;font-size:12px}.vvs-demo{padding:16px}}

.followup-demo h3:focus{outline:none}.followup-demo h3{scroll-margin-top:110px}.followup-demo .fu-copy{white-space:pre-line}

function mount(host, { reset = false, onClose = () => {}, scenario = null } = {}) {
  if (!session || reset) {
    const seed = scenario || session?.scenario;
    const next = initial();
    if (seed) {
      for (const key of ['name','email','need']) if (typeof seed[key] === 'string') next[key] = seed[key].slice(0,1200);
      next.draft = { ...next.draft, title: String(seed.title || 'VVS-forespørsel').slice(0,120),
        description: 'Omfang og tidspunkt må avklares med kunden.', amount: '' };
      next.events = ['VVS-forespørsel mottatt · fiktiv eksempelsak J-1001.'];
    }
    session = { state: next, revision: 0, scenario: seed }; sessions.set(host, session);
  }
    const form = newForm(), input = field(form, 'Spørsmål til kunden', 'question', state.question || (session.scenario ? 'Når passer det at vi ringer for å avklare arbeidet?' : 'Hvilken dag neste uke passer best, og er leiligheten tømt?'), 'textarea'); input.maxLength = 800;
    const form = newForm(), input = field(form, 'Din avklaring', 'answer', state.answer || (session.scenario ? 'Ring meg gjerne fredag etter klokken 14.' : 'Fredag passer best. Leiligheten vil være tømt.'), 'textarea'); input.maxLength = 800;
    if (session.revision > 1 && h?.scrollIntoView) h.scrollIntoView({block:'nearest',behavior:'instant'});

  vvs: { client: 'jemlio', title: 'Jemlio for rørleggere', industry: 'Annen tjenestebedrift', greeting: 'Spør om VVS-henvendelser, prisforslag og oppfølging. Ekte SMS og telefonruting må kobles til separat; pilotvisningen sender ingenting.', questions: ['Hva gjør Jemlio for rørleggere?', 'Hvordan fungerer ubesvarte anrop?', 'Kobles Jemlio til Cordel eller SmartDok?'] },
let followup = null, vvsDemo = null;
function showVvs() {
  demo.reset('', []);
  const host = $('demo-messages'); host.setAttribute('role','region'); host.setAttribute('aria-live','off');
  vvsDemo = window.JemlioVvsDemo.mount(host, { onClose: () => {
    host.setAttribute('role','log');host.setAttribute('aria-live','polite');
    demo.reset(examples.vvs.greeting, examples.vvs.questions);
    $('followup-chat-return').hidden=false;$('demo-input').focus();
  }});
  $('followup-chat-return').hidden=true;
}
  if (kind === 'vvs' && window.JemlioVvsDemo) showVvs();
  else if (kind === 'workflow' && window.JemlioFollowupDemo) showFollowup();
  if (selected === 'vvs' && vvsDemo) { vvsDemo.reset(); return; }
$('followup-chat-return')?.addEventListener('click', () => { if (selected==='vvs' && window.JemlioVvsDemo) showVvs(); else if (window.JemlioFollowupDemo) showFollowup(); });
document.querySelectorAll('[data-open-vvs]').forEach(a=>a.addEventListener('click',()=>select('vvs')));
if (window.JemlioVvsDemo) select('vvs');
